#include <vector>
#include <string>
using namespace std;

class Solution {
public:
    char slowestKey(vector<int>& releaseTimes, string keysPressed) {
        char best_char = keysPressed[0];
        int max_duration = releaseTimes[0];
        for (size_t i = 1; i < releaseTimes.size(); ++i) {
            int dur = releaseTimes[i] - releaseTimes[i - 1];
            char c = keysPressed[i];
            if (dur > max_duration || (dur == max_duration && c > best_char)) {
                max_duration = dur;
                best_char = c;
            }
        }
        return best_char;
    }
};

class Solution {
    public char slowestKey(int[] releaseTimes, String keysPressed) {
        char bestChar = keysPressed.charAt(0);
        int maxDuration = releaseTimes[0];
        for (int i = 1; i < releaseTimes.length; ++i) {
            int dur = releaseTimes[i] - releaseTimes[i - 1];
            char c = keysPressed.charAt(i);
            if (dur > maxDuration || (dur == maxDuration && c > bestChar)) {
                maxDuration = dur;
                bestChar = c;
            }
        }
        return bestChar;
    }
}

/**
 * @param {number[]} releaseTimes
 * @param {string} keysPressed
 * @return {character}
 */
var slowestKey = function(releaseTimes, keysPressed) {
    let bestChar = keysPressed[0];
    let maxDuration = releaseTimes[0];
    for (let i = 1; i < releaseTimes.length; ++i) {
        const dur = releaseTimes[i] - releaseTimes[i - 1];
        const c = keysPressed[i];
        if (dur > maxDuration || (dur === maxDuration && c > bestChar)) {
            maxDuration = dur;
            bestChar = c;
        }
    }
    return bestChar;
};
